# Let's enumerate all possible sequences of length 3
# where each element is between 0 and 3
from itertools import product

solutions = []
for seq in product(range(4), repeat=3):
    # Check the magic condition
    ok = True
    for i in range(3):
        if seq.count(i) != seq[i]:
            ok = False
            break
    if ok:
        solutions.append(list(seq))
        print(f"Found: {list(seq)}")

print(f"Total solutions: {len(solutions)}")

# Also check if sum condition holds
for seq in product(range(4), repeat=3):
    if sum(seq) == 3:
        print(f"Sum=3: {list(seq)}")
